package slack

import (
	"context"
	_ "embed"
	"encoding/json"
	"github.com/bitskyai/chatkeeper/pkg/pluginapi"
	"net/url"
	"sort"
	"strings"
	"sync"
)

// emoji/emoji.json is generated by tools/generate-emoji.py from iamcal/emoji-data
// (MIT License, see emoji/LICENSE), which uses Slack's standard short names. The
// source commit and SHA-256 are pinned in the generator and emoji/NOTICE.
//
//go:embed emoji/emoji.json
var emojiJSON []byte

type emojiEntry struct {
	Name, Glyph, Category string
	Aliases               []string
}

var emojiTable = sync.OnceValue(func() struct {
	list   []emojiEntry
	byName map[string]emojiEntry
} {
	var raw struct {
		Categories []string `json:"categories"`
		Emoji      [][]any  `json:"emoji"`
	}
	if json.Unmarshal(emojiJSON, &raw) != nil {
		panic("invalid embedded emoji table")
	}
	out := struct {
		list   []emojiEntry
		byName map[string]emojiEntry
	}{byName: map[string]emojiEntry{}}
	for _, row := range raw.Emoji {
		if len(row) != 4 {
			panic("invalid embedded emoji row")
		}
		name, _ := row[0].(string)
		glyph, _ := row[1].(string)
		idx, _ := row[2].(float64)
		aliases, _ := row[3].(string)
		e := emojiEntry{Name: name, Glyph: glyph, Category: raw.Categories[int(idx)], Aliases: strings.Fields(aliases)}
		out.list = append(out.list, e)
		out.byName[name] = e
		for _, a := range e.Aliases {
			out.byName[a] = e
		}
	}
	return out
})

// Glyph returns the Unicode character for a standard Slack emoji name, ignoring
// skin-tone suffixes such as "+1::skin-tone-3".
func Glyph(name string) string {
	base, _, _ := strings.Cut(name, "::")
	return emojiTable().byName[base].Glyph
}

// StandardEmoji lists standard emoji as picker choices in display order.
func StandardEmoji() []pluginapi.Choice {
	t := emojiTable()
	out := make([]pluginapi.Choice, 0, len(t.list))
	for _, e := range t.list {
		out = append(out, pluginapi.Choice{ID: e.Name, Label: ":" + e.Name + ":", Glyph: e.Glyph, Group: e.Category, Keywords: strings.Join(append([]string{e.Name}, e.Aliases...), " ")})
	}
	return out
}

// customEmoji lists workspace emoji via emoji.list. It needs the optional
// emoji:read scope; callers treat any error as "custom emoji unavailable".
func customEmoji(ctx context.Context, c *Client) ([]pluginapi.Choice, error) {
	doc, e := c.Call(ctx, "emoji.list", nil)
	if e != nil {
		return nil, e
	}
	m, ok := doc["emoji"].(map[string]any)
	if !ok {
		return nil, pluginapi.ErrInvalid
	}
	names := []string{}
	for name := range m {
		if reactionPattern.MatchString(name) {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	out := []pluginapi.Choice{}
	for _, name := range names {
		value, _ := m[name].(string)
		choice := pluginapi.Choice{ID: name, Label: ":" + name + ":", Group: "Custom", Keywords: name}
		if target, alias := strings.CutPrefix(value, "alias:"); alias {
			if g := Glyph(target); g != "" {
				choice.Glyph = g
			} else if v, ok := m[target].(string); ok && emojiImage(v) {
				choice.Image = v
			}
		} else if emojiImage(value) {
			choice.Image = value
		}
		if len(out) >= 5000 {
			break
		}
		out = append(out, choice)
	}
	return out, nil
}

// emojiImage accepts only Slack's HTTPS emoji CDN.
func emojiImage(raw string) bool {
	u, e := url.Parse(raw)
	return e == nil && u.Scheme == "https" && u.User == nil && u.Port() == "" && u.Hostname() == "emoji.slack-edge.com"
}

// Reactions renders stored reactions with standard glyphs; custom emoji show
// their name because archived pages never load remote images.
func (Hooks) Reactions(_ context.Context, m pluginapi.Message) ([]pluginapi.ReactionView, error) {
	root, e := normalizeRoot(map[string]any{"ts": "0.0", "reactions": m["reactions"]})
	if _, has := m["reactions"]; !has {
		return nil, nil
	}
	if e != nil {
		return nil, e
	}
	out := []pluginapi.ReactionView{}
	for _, r := range root.Reactions {
		out = append(out, pluginapi.ReactionView{Name: r.Name, Glyph: Glyph(r.Name), Count: r.Count})
	}
	return out, nil
}
